INSERT INTO "chatbot_knowledge" ("id", "updated_at", "topic", "question", "answer", "tags", "enabled") SELECT gen_random_uuid(), CURRENT_TIMESTAMP, 'Agentic coding', 'How does Jhon use AI when coding?', 'Jhon uses AI agents to help plan, implement, and iterate on web development work. He remains responsible for architecture, reviews generated code, and tests how the parts work together. AI assistance is part of his workflow; it does not replace his ownership of the delivered website.', 'ai,agentic,coding,workflow,review', true WHERE NOT EXISTS (SELECT 1 FROM "chatbot_knowledge" WHERE "question" = 'How does Jhon use AI when coding?');
INSERT INTO "chatbot_knowledge" ("id", "updated_at", "topic", "question", "answer", "tags", "enabled") SELECT gen_random_uuid(), CURRENT_TIMESTAMP, 'DEOS contributions', 'What did Jhon contribute to DEOS?', 'Jhon Lisley Jeresano contributed to DEOS at WWC Yellow Bumblebee Corp. His work includes reporting forms and validation, PDF generation, spatial analytics and heatmaps, dashboard and admin improvements, ownership-transfer fixes, and client/server user manuals. DEOS is a team project; the current Projects section contains his detailed contribution scope.', 'deos,projects,contributions,reporting', true WHERE NOT EXISTS (SELECT 1 FROM "chatbot_knowledge" WHERE "question" = 'What did Jhon contribute to DEOS?');
INSERT INTO "chatbot_knowledge" ("id", "updated_at", "topic", "question", "answer", "tags", "enabled") SELECT gen_random_uuid(), CURRENT_TIMESTAMP, 'PDEA ownership', 'Did Jhon build the PDEA Unity app?', 'No. Jhon built the entire website portion of PDEA Virtual Museum and installed and integrated its Unity 3D app into the website. Other developers built the Unity application itself.', 'pdea,unity,museum,ownership,projects', true WHERE NOT EXISTS (SELECT 1 FROM "chatbot_knowledge" WHERE "question" = 'Did Jhon build the PDEA Unity app?');
INSERT INTO "chatbot_knowledge" ("id", "updated_at", "topic", "question", "answer", "tags", "enabled") SELECT gen_random_uuid(), CURRENT_TIMESTAMP, 'OADR recruitment', 'What did Jhon build for OADR?', 'Jhon developed the entire OADR recruitment process and the performance management, awards, and recognition pages. These contributions were made at WWC Yellow Bumblebee Corp.; the broader OADR system is a team project.', 'oadr,recruitment,awards,performance,projects', true WHERE NOT EXISTS (SELECT 1 FROM "chatbot_knowledge" WHERE "question" = 'What did Jhon build for OADR?');
INSERT INTO "chatbot_knowledge" ("id", "updated_at", "topic", "question", "answer", "tags", "enabled") SELECT gen_random_uuid(), CURRENT_TIMESTAMP, 'Project scope', 'Did Jhon build all the WWC projects alone?', 'No. His scope differs by project: he contributed selected DEOS features, built the whole PDEA website and integrated a Unity app built by others, and built the OADR recruitment process plus the named HR pages. He does not claim sole authorship of the wider DEOS or OADR platforms.', 'wwc,ownership,scope,projects,team', true WHERE NOT EXISTS (SELECT 1 FROM "chatbot_knowledge" WHERE "question" = 'Did Jhon build all the WWC projects alone?');
INSERT INTO "chatbot_knowledge" ("id", "updated_at", "topic", "question", "answer", "tags", "enabled") SELECT gen_random_uuid(), CURRENT_TIMESTAMP, 'Project inquiries', 'What information should I include in a project inquiry?', 'Include what the website should accomplish, who will use it, essential features, whether you already have a design or existing code, integrations, your target launch date, and an approximate budget if known. Avoid sending passwords or API keys. Jhon can then discuss scope and confirm an estimate.', 'inquiry,requirements,brief,pricing,timeline', true WHERE NOT EXISTS (SELECT 1 FROM "chatbot_knowledge" WHERE "question" = 'What information should I include in a project inquiry?');
INSERT INTO "chatbot_knowledge" ("id", "updated_at", "topic", "question", "answer", "tags", "enabled") SELECT gen_random_uuid(), CURRENT_TIMESTAMP, 'Start a project', 'How can I discuss a website project?', 'Use the contact section to describe the website you want to build. Start with its purpose and essential features; add a preferred launch date and budget if known. Jhon will need to confirm feasibility, scope, pricing, and availability personally.', 'services,website,inquiry,contact', true WHERE NOT EXISTS (SELECT 1 FROM "chatbot_knowledge" WHERE "question" = 'How can I discuss a website project?');
INSERT INTO "chatbot_knowledge" ("id", "updated_at", "topic", "question", "answer", "tags", "enabled") SELECT gen_random_uuid(), CURRENT_TIMESTAMP, 'Photography', 'Where can I see Jhon''s photography?', 'The Photography section on this same page contains the photographs he has published. Open an image to view its caption and location. If it is empty, he has not published photographs yet.', 'photography,photos,gallery', true WHERE NOT EXISTS (SELECT 1 FROM "chatbot_knowledge" WHERE "question" = 'Where can I see Jhon''s photography?');
INSERT INTO "chatbot_knowledge" ("id", "updated_at", "topic", "question", "answer", "tags", "enabled") SELECT gen_random_uuid(), CURRENT_TIMESTAMP, 'Verification', 'Can you guarantee a quote or deadline?', 'No. The assistant cannot confirm pricing, delivery dates, bookings, or contractual commitments. Use the contact section so Jhon can review the requirements and provide a confirmed estimate.', 'pricing,deadline,quote', true WHERE NOT EXISTS (SELECT 1 FROM "chatbot_knowledge" WHERE "question" = 'Can you guarantee a quote or deadline?');
INSERT INTO "chatbot_knowledge" ("id", "updated_at", "topic", "question", "answer", "tags", "enabled") SELECT gen_random_uuid(), CURRENT_TIMESTAMP, 'Accuracy', 'What do you base your answers on?', 'Answers use the portfolio''s published project descriptions, listed technologies, experience, certifications, current site information, and enabled admin knowledge entries. When those sources do not establish a fact, the assistant should ask for clarification or suggest contacting Jhon.', 'accuracy,sources,knowledge', true WHERE NOT EXISTS (SELECT 1 FROM "chatbot_knowledge" WHERE "question" = 'What do you base your answers on?');
